package e.e.a;
import android.graphics.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import java.io.*;import java.nio.file.*;import java.util.*;import java.util.zip.*;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(manifest=Config.NONE,sdk=28) @GraphicsMode(GraphicsMode.Mode.NATIVE)
public class LegacyIcons191Test {
 static final String ROOT="/workspace/scratch/c1724b4b8d1a/";
 static Map<String,byte[]> resources(String version)throws Exception{byte[] nested;try(ZipFile zip=new ZipFile(ROOT+"nicoid-re-1.9.1-dev."+version+".mpp")){nested=zip.getInputStream(zip.getEntry("nicoid/resources.zip")).readAllBytes();}Map<String,byte[]> out=new HashMap<>();try(ZipInputStream zip=new ZipInputStream(new ByteArrayInputStream(nested))){ZipEntry entry;while((entry=zip.getNextEntry())!=null)out.put(entry.getName(),zip.readAllBytes());}return out;}
 @Test public void vectorDictionaryIconsCannotBeDecodedByLegacyBitmapLoader()throws Exception{Map<String,byte[]> broken=resources("4");for(String name:new String[]{"dicon","dicoff"}){byte[] bytes=broken.get("res/drawable-nodpi/"+name+".xml");assertNotNull(bytes);assertNull("legacy bitmap loader rejects XML: "+name,BitmapFactory.decodeByteArray(bytes,0,bytes.length));}}
 @Test public void everyRefreshedBitmapCanBeDecodedWithOriginalBoundsAndVisiblePixels()throws Exception{Map<String,byte[]> original=resources("3"),fixed=resources("5");Set<String> names=new HashSet<>(Arrays.asList("play","pause","next","prev","fullscreen","normalscreen","popup","repeaton","repeatoff","commenton","commentoff","commentpost","info","lock","unlock","menubutton","dicon","dicoff","ic_menu_search","ic_drawer","ic_menu_share","ic_menu_recent_history","combig","commedium","comsmall","comue","comnaka","comshita"));int checked=0;for(String path:original.keySet()){String name=path.substring(path.lastIndexOf('/')+1);if(!name.endsWith(".png")||!names.contains(name.substring(0,name.length()-4)))continue;byte[] bytes=fixed.get(path);assertNotNull("missing bitmap: "+path,bytes);Bitmap after=BitmapFactory.decodeByteArray(bytes,0,bytes.length);assertNotNull("not decodable: "+path,after);BitmapFactory.Options bounds=new BitmapFactory.Options();bounds.inJustDecodeBounds=true;byte[] before=original.get(path);BitmapFactory.decodeByteArray(before,0,before.length,bounds);assertEquals(path,bounds.outWidth,after.getWidth());assertEquals(path,bounds.outHeight,after.getHeight());boolean visible=false;for(int y=0;y<after.getHeight()&&!visible;y++)for(int x=0;x<after.getWidth();x++)if(Color.alpha(after.getPixel(x,y))>100){visible=true;break;}assertTrue("empty glyph: "+path,visible);after.recycle();checked++;}assertEquals(37,checked);}
}
